     app.get('/inscricoes/:id', (req, res) => {
       const row = db.prepare('SELECT * FROM inscricoes WHERE id = ?').get(req.params.id);
       if (!row) {
         return res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Inscrição não encontrada' });
       }
